import React, { useLayoutEffect, useState, useEffect } from "react";
import { Form } from "react-bootstrap";
import MetricPanel from "./components/MetricPanel";
import BorderBeam from "./components/BorderBeam";
import AuthModal from "./components/AuthModal";
import platformsData from "./data/platforms.json";
import "./App.css";
import LlmPage from "./pages/LlmPage";
import ImagePage from "./pages/ImagePage";
import VideoPage from "./pages/VideoPage";
import AudioPage from "./pages/AudioPage";
import CategoryPage from "./pages/CategoryPage";
import PromptNodePage from "./pages/PromptNodePage";
import GuideInstallModal from "./components/GuideInstallModal";
import { me } from "./api/auth";
import Mypage from "./pages/Mypage";

/* =========================
   HEADER
   ========================= */
function Header({ user, onLoginClick, onLogout, onGoMypage, hidden = false }) {
  const [lang, setLang] = useState("KO");

  const changeLang = (value) => {
    setLang(value);
    console.log("선택된 언어:", value);
  };

  const getInitials = (name = "") => {
    const cleaned = String(name || "").trim();
    if (!cleaned) return "U";
    const parts = cleaned.split(/\s+/).filter(Boolean);
    const first = parts[0]?.[0] || "U";
    const second = parts.length > 1 ? (parts[parts.length - 1]?.[0] || "") : "";
    return (first + second).toUpperCase();
  };

  const initials = user?.name ? getInitials(user.name) : "U";

  return (
    <header className={`header ${hidden ? "headerHidden" : ""}`}>
      <div className="wrap headerin">
        <div className="headerleft">
          <div className="headerlogo">LOGO</div>
        </div>

        <div className="headerright">
          <div className="dropdown">
            <button
              className="headertxt"
              type="button"
              data-bs-toggle="dropdown"
              aria-expanded="false"
              aria-label="Language selector"
            >
              <i className="bi bi-globe"></i>
            </button>

            <ul className="dropdown-menu dropdown-menu-end">
              <li>
                <button className="dropdown-item" onClick={() => changeLang("KO")}>
                  한국어
                </button>
              </li>
              <li>
                <button className="dropdown-item" onClick={() => changeLang("EN")}>
                  English
                </button>
              </li>
            </ul>
          </div>

          {!user ? (
            <button className="headertxt" type="button" onClick={onLoginClick}>
              로그인
            </button>
          ) : (
            <div className="dropdown">
              <button
                className="headertxt userMenuBtn"
                type="button"
                data-bs-toggle="dropdown"
                aria-expanded="false"
                aria-label="User menu"
              >
                <span className="userAvatarSm" aria-hidden="true">{initials}</span>
                <span className="userName">{user?.name}</span>
              </button>

              <ul className="dropdown-menu dropdown-menu-end">
                <li>
                  <div className="dropdown-item-text userDropdownEmail">
                    {user?.email}
                  </div>
                </li>

                <li><hr className="dropdown-divider" /></li>

                <li>
                  <button className="dropdown-item" type="button" onClick={onGoMypage}>
                    mypage
                  </button>
                </li>

                <li>
                  <button className="dropdown-item disabled" type="button" tabIndex={-1} aria-disabled="true">
                    plan&amp;billing
                  </button>
                </li>

                <li><hr className="dropdown-divider" /></li>

                <li>
                  <button className="dropdown-item dropdownLogout" type="button" onClick={onLogout}>
                    로그아웃
                  </button>
                </li>
              </ul>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

/* =========================
   MAIN SECTION
   ========================= */

function Main({ onOpenPromptNode }) {
  return (
    <section className="main">
      <video
        className="mainvideo"
        src="/static/video/ai_graphic.mp4"
        autoPlay
        muted
        loop
        playsInline
      />
      <div className="mainin wrap">
        <div className="mainlogo">LOGO</div>

        <div className="maintxtbox">
          <p className="mainlead">WELCOME TO AI PLATFORM</p>
          <p className="mainsub">
            AI 플랫폼을 한 번에 검색하고
            <br />
            UI/UX 개선을 빠르게 진행하세요
          </p>
        </div>

        {/* search bar */}
        <div className="search">
          <div className="searchin">
            <i className="bi bi-search"></i>
            <input className="searchinput" placeholder="Search AI platform..." />
          </div>
          <div className="searchbeam">
            <BorderBeam />
          </div>
        </div>

        <div className="mainbtnrow">
          <button className="mainbtn" type="button" onClick={onOpenPromptNode}>
            PROMPT NODE
          </button>
        </div>
      </div>
    </section>
  );
}

/* =========================
   MENU SECTION
   ========================= */

function Menu({ menuselect, onmenuclick }) {
  const menu = ["ALL", "LLM", "IMAGE", "VIDEO", "AUDIO", "ETC"];
  return (
    <section className="menu">
      <div className="wrap menuin">
        {menu.map((m) => (
          <button
            key={m}
            type="button"
            className={`menubtn ${menuselect === m ? "menubtnActive" : ""}`}
            onClick={() => onmenuclick(m)}
          >
            {m}
          </button>
        ))}
      </div>
    </section>
  );
}

/* =========================
   FOOTER
   ========================= */

function Footer() {
  return (
    <footer className="footer">
      <div className="footerin">
        <div className="wrap footerrow">
          <div className="footerleft">
            <div className="footerlogo">LOGO</div>
          </div>

          <div className="footermenu">
            <span className="footertxt">ALL</span>
            <span className="footertxt">LLM</span>
            <span className="footertxt">IMAGE</span>
            <span className="footertxt">VIDEO</span>
            <span className="footertxt">AUDIO</span>
          </div>

          <div className="footerright">
            <div className="snslogo">
              <span aria-label="YouTube">
                <i className="bi bi-youtube"></i>
              </span>
              <span aria-label="Facebook">
                <i className="bi bi-facebook"></i>
              </span>
              <span aria-label="X">
                <i className="bi bi-twitter-x"></i>
              </span>
              <span aria-label="instagram">
                <i className="bi bi-instagram"></i>
              </span>
            </div>
          </div>
        </div>
      </div>

      <div className="footercopy">
        <div className="wrap copy">@2025 All right reserved</div>
      </div>
    </footer>
  );
}

/* =========================
   APP
   ========================= */

export default function App() {
  const [menuselect, setmenuselect] = useState("ALL");

  // 로그인 모달/유저 상태 추가
  const [authOpen, setAuthOpen] = useState(false);
  const [user, setUser] = useState(null);

  // 페이지 상태 추가 (HOME / PROMPT_NODE / MYPAGE)
  const [page, setPage] = useState("HOME");

  // 확장프로그램 설치 여부 감지 + 설치 안내 모달
  const [guideExtensionReady, setGuideExtensionReady] = useState(false);
  const [guideInstallOpen, setGuideInstallOpen] = useState(false);

  // 저장된 토큰이 있으면 사용자 정보를 복구
  useEffect(() => {
    const token =
      window.localStorage.getItem("access_token") ||
      window.sessionStorage.getItem("access_token");

    if (!token) return;

    me(token)
      .then((data) => {
        if (data?.user) setUser(data.user);
      })
      .catch(() => {
        window.localStorage.removeItem("access_token");
        window.sessionStorage.removeItem("access_token");
        setUser(null);
      });
  }, []);

  // 로그인하지 않은 상태에서 MYPAGE 진입 시 로그인 모달로 유도
  useEffect(() => {
    if (page !== "MYPAGE") return;
    if (user) return;
    setAuthOpen(true);
    setPage("HOME");
  }, [page, user]);

  function onmenuclick(categoryname) {
    setmenuselect(categoryname);
  }

  /* ======== PromptNode -> Main ======= */

  // HOME 상태 시 기존 스크롤 동작
  useLayoutEffect(() => {
    if (page !== "HOME") return;
    if (menuselect === "ALL") return;
    const el = document.getElementById("metric-anchor");
    if (!el) return;
    el.scrollIntoView({ behavior: "smooth", block: "start" });
  }, [menuselect, page]);

  function openAuth() {
    setAuthOpen(true);
  }

  function logout() {
    window.localStorage.removeItem("access_token");
    window.sessionStorage.removeItem("access_token");
    setUser(null);
    setPage("HOME");
    setmenuselect("ALL");
  }

  // PROMPT NODE 페이지 이동/복귀
  function openPromptNodePage() {
    setPage("PROMPT_NODE");
  }

  function backToHome() {
    setPage("HOME");
  }

  function openMypage() {
    if (!user) {
      openAuth();
      return;
    }
    setPage("MYPAGE");
  }

  /* ======== PromptNode  ======= */

  // 확장프로그램이 "설치됨" 신호를 보내면 ready 처리
  useEffect(() => {
    function handleExtensionReadyMessage(e) {
      if (!e?.data) return;
      if (e.data.type === "AI_GUIDE_EXTENSION_READY") {
        setGuideExtensionReady(true);
      }
    }
    window.addEventListener("message", handleExtensionReadyMessage);
    return () => window.removeEventListener("message", handleExtensionReadyMessage);
  }, []);

  function startChatGptGuide() {
    // 설치돼 있으면 바로 가이드 실행
    if (guideExtensionReady) {
      window.postMessage({ type: "AI_GUIDE_START" }, "*");
      return;
    }
    // 미설치면 설치 안내 모달
    setGuideInstallOpen(true);
  }

  // 플랫폼 데이터(카드) - 필요시 사용
  const platforms = platformsData || [];

  return (
    <div className="app">
      <Header
        user={user}
        onLoginClick={openAuth}
        onLogout={logout}
        onGoMypage={openMypage}
        hidden={page === "PROMPT_NODE"}
      />

      {page === "PROMPT_NODE" ? (
        <main className="nodeMain">
          <PromptNodePage onBack={backToHome} />
        </main>
      ) : page === "MYPAGE" ? (
        <main className="mypageMain">
          <Mypage user={user} />
        </main>
      ) : (
        <main>
          {/* PROMPT NODE 클릭 시 openPromptNodePage */}
          <Main onOpenPromptNode={openPromptNodePage} />
          <Menu menuselect={menuselect} onmenuclick={onmenuclick} />

          {menuselect === "ALL" ? (
            <>
              {/* LLM과 IMAGE는 selectable={false}로 설정 (설명창 안나옴) */}
              <LlmPage onGuideStart={startChatGptGuide} selectable={false} />
              <ImagePage selectable={false} />
              {/* VIDEO와 AUDIO는 selectable={true}로 설정 (설명창 나옴) */}
              <VideoPage selectable={true} />
              <AudioPage selectable={true} />
            </>
          ) : (
            <CategoryPage categoryname={menuselect} onGuideStart={startChatGptGuide} />
          )}
        </main>
      )}

      {page !== "PROMPT_NODE" && <Footer />}

      {/* 확장프로그램 설치 안내 모달 */}
      <GuideInstallModal
        show={guideInstallOpen}
        onHide={() => setGuideInstallOpen(false)}
      />

      <AuthModal show={authOpen} onHide={() => setAuthOpen(false)} onAuthed={(u) => setUser(u)} />
    </div>
  );
}
